 F(1, DEF, "This code should print `hi`, but it crashes. Fix it.", 'say_hi()\ndef say_hi():\n    print("hi")', 'def say_hi():\n    print("hi")\nsay_hi()', "Python runs from top to bottom, so a function must be defined before it is called."),
 T(1, RET, 'def double(n):\n    print(n * 2)\n\nresult = double(4)\nprint(result)', "`double()` prints 8 but has no `return`, so it gives back `None`, and `result` is `None`."),
 F(1, PARAM, "This code should print `Hello Guest`, but it crashes. Fix it by giving `name` a default value.", 'def greet(name):\n    print("Hello", name)\n\ngreet()', 'def greet(name="Guest"):\n    print("Hello", name)\n\ngreet()', "A call must give every parameter that has no default. `name=\"Guest\"` makes the argument optional."),
 # ---------- Medium ----------
 W(2, RET, 'Write `is_eligible(age)` that returns `True` when `age` is 18 or more, using one `return` line. Print `is_eligible(17)` and `is_eligible(18)` with one `print()`.', '# def is_eligible(age):\n', 'def is_eligible(age):\n    return age >= 18\n\nprint(is_eligible(17), is_eligible(18))', "A comparison already gives `True` or `False`, so you can return it directly, without `if`."),
 W(2, SEVERAL, 'Write `min_max(nums)` that returns the smallest and the largest number. For `[12, 3, 41, 7]`, unpack the result and print `Min: 3 Max: 41`.', '# def min_max(nums):\n', 'def min_max(nums):\n    return min(nums), max(nums)\n\nlow, high = min_max([12, 3, 41, 7])\nprint("Min:", low, "Max:", high)', "`return a, b` sends back a tuple, which the caller unpacks into two names."),
 T(2, DEFAULT, 'def intro(name, city="Pune"):\n    print(name, "from", city)\n\nintro("Asha")\nintro(city="Goa", name="Ravi")', "The first call uses the default city. Keyword arguments can come in any order, because each one is matched by name."),
 F(2, RET, "This function should add up all the prices and print `60`, but it prints `10`. Fix it.", 'def total(prices):\n    s = 0\n    for p in prices:\n        s += p\n        return s\n\nprint(total([10, 20, 30]))', 'def total(prices):\n    s = 0\n    for p in prices:\n        s += p\n    return s\n\nprint(total([10, 20, 30]))', "`return` ends the function at once. Inside the loop it returns after the first price. Move it out of the loop."),
 W(2, BUILTIN, 'Write `grade(marks)` that returns `"A"` for 90 or more, `"B"` for 75 or more, `"C"` for 50 or more, and `"F"` below that. Print the grades of `[95, 80, 40]` as a list, using a comprehension.', '# def grade(marks):\n', 'def grade(marks):\n    if marks >= 90:\n        return "A"\n    elif marks >= 75:\n        return "B"\n    elif marks >= 50:\n        return "C"\n    return "F"\n\nprint([grade(m) for m in [95, 80, 40]])', "Your own functions work anywhere a built-in does, including inside a comprehension."),
 W(2, DOC, 'Write `area(length, width)` with the docstring `Return the area of a rectangle.` Print `area(4, 5)`, then print the docstring with `area.__doc__`.', '# def area(length, width):\n', 'def area(length, width):\n    """Return the area of a rectangle."""\n    return length * width\n\nprint(area(4, 5))\nprint(area.__doc__)', "A docstring is the first string inside the function. Python keeps it in `__doc__`, and `help()` shows it."),
 T(2, SEVERAL, 'def stats(a, b):\n    return a + b, a * b\n\nx = stats(3, 4)\nprint(x, type(x))', "Two values after `return` are packed into one tuple."),
